import{_ as o,l as i,o as e,c as n,v as t,p as E,x as l,d as s,i as d,S as B}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"MTEB","description":"","frontmatter":{"title":"MTEB","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/mteb.md","filePath":"llm/mteb.md","lastUpdated":1789023840000}'),m={name:"llm/mteb.md"};function h(p,a,T,A,_,M){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="mteb" tabindex="-1">MTEB <a class="header-anchor" href="#mteb" aria-label="Permalink to &quot;MTEB&quot;">​</a></h1><div class="epigraph"><p>检索、聚类、分类、改写、语义相似度不是同一个几何。一张嵌入榜必须分任务报，禁止用单任务召回签发通用嵌入。</p><footer>—— Muennighoff 等, MTEB</footer></div><p><a href="/llm/splade">上一课</a>学习稀疏词表权重，倒排可含扩展词；稀疏正则是可用性条件，常作混合一路。前课从 InfoNCE、难负例、嵌套维、指令、多向量、BM25、SPLADE 堆出一排配方。缺口是比较协议：不能只用单任务召回签发通用嵌入。Muennighoff 等人的 MTEB 把多种任务收成套件；本课写怎么读这张榜，不重推 SPLADE 的正则。后课长文档嵌入默认：MTEB 多数任务偏短文，长文要另测。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只在 MS MARCO 上刷召回，会选出非对称检索模型，聚类与 STS 可能很差。只在 STS 上刷，会选出对称相似度模型，检索标识符弱。MTEB 的点是强制多任务：检索、重排、聚类、分类、对相似度、摘要等。总分平均会重演 MMLU 课的陷阱——专长被抹平。应看任务族，尤其是与产品同构的那一族。</p><p>指令嵌入必须用官方任务指令；不用指令的模型与用指令的模型分表。多语言子集（MMTEB 等扩展）与英文主表不可互换，见<a href="/llm/multilingual-benchmarks">多语言基准</a>同一纪律。</p><p><span class="marginnote">MTEB 分数绑定评测脚本版本与是否归一化、是否用特定池化。换脚本等于换榜。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>发布：按任务族报，附模型类型（稠密双塔 / 稀疏 / 多向量）、最大输入长度、是否指令。不要把交叉编码器的重排分写进双塔表。污染：部分任务来自公开数据集，可能进过对比训练；应披露训练任务列表，与评测重叠的任务降级为回归。</p>',9)),(e(),E(B,null,{default:l(()=>[d(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20EMB%5B%22%E5%B5%8C%E5%85%A5%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20RET%5B%22%E6%A3%80%E7%B4%A2%E6%97%8F%22%5D%0A%20%20EMB%20--%3E%20CLU%5B%22%E8%81%9A%E7%B1%BB%20%2F%20%E5%88%86%E7%B1%BB%22%5D%0A%20%20EMB%20--%3E%20STS%5B%22%E5%AF%B9%E7%A7%B0%E7%9B%B8%E4%BC%BC%E5%BA%A6%22%5D%0A%20%20RET%20--%3E%20FAM%5B%22%E5%88%86%E6%97%8F%E8%AF%BB%E6%A6%9C%22%5D%0A%20%20CLU%20--%3E%20FAM%0A%20%20STS%20--%3E%20FAM%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>不同任务对应不同的「正对」定义。检索正对是相关文档，聚类正对是同类，STS 正对是同义句。同一 InfoNCE 无法同时最优，指令与多任务采样是在帕累托面上选点。MTEB 平均分奖励折中模型；产品应在面上选自己的点，而不是选平均冠军。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>套件对长文档、代码、法律条款、多模态覆盖不足。下一课补长文档；再后课补多模态嵌入。不要用 MTEB 总分代理 RAG 端到端。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MTEB 是多任务嵌入协议，按族读，不单报总分。</li><li>指令、长度、模型类型必须与分数绑定。</li><li>训练任务与评测重叠要披露。</li><li>出处：Muennighoff 等 <em>MTEB</em>。</li></ul>',6))])}const u=o(m,[["render",h]]);export{f as __pageData,u as default};
